async def test_list_tasks_filters_by_id(client: AsyncClient, session: AsyncSession) -> None:
    records = [await make_task(session) for _ in range(2)]
    values = [to_jsonable_python(r.id) for r in records]
    first = str(records[0].id)

    ids = await _ids(client, {"id": [values[0]]})

    assert first in ids
    if values[1] != values[0]:
        assert str(records[1].id) not in ids
    ids = await _ids(client, {"id": values})
    assert {first, str(records[1].id)} <= set(ids)


